 void Start(){var args=Environment.GetCommandLineArgs();int journey=Array.IndexOf(args,"--capture-v24");if(journey>=0&&journey+1<args.Length){StartCoroutine(CaptureJourney(args[journey+1]));return;}int relics=Array.IndexOf(args,"--capture-relic-attacks");if(relics>=0&&relics+1<args.Length){StartCoroutine(CaptureRelicAttacks(args[relics+1]));return;}int features=Array.IndexOf(args,"--capture-v22");if(features>=0&&features+1<args.Length){StartCoroutine(CaptureFeaturesV22(args[features+1]));return;}int combat=Array.IndexOf(args,"--capture-combat");if(combat>=0&&combat+1<args.Length){StartCoroutine(CaptureCombatFix(args[combat+1]));return;}int nh=Array.IndexOf(args,"--capture-heroes");if(nh>=0&&nh+1<args.Length){StartCoroutine(CaptureNewHeroes(args[nh+1]));return;}int models=Array.IndexOf(args,"--capture-models");if(models>=0&&models+1<args.Length){StartCoroutine(CaptureModelStudio(args[models+1]));return;}int movie=Array.IndexOf(args,"--capture-animation");if(movie>=0&&movie+1<args.Length){StartCoroutine(CaptureAnimationMovie(args[movie+1]));return;}int i=Array.IndexOf(args,"--capture-ui");if(i>=0&&i+1<args.Length)StartCoroutine(CapturePreview(args[i+1]));}
 IEnumerator CapturePreview(string folder){verifying=true;Application.runInBackground=true;Directory.CreateDirectory(folder);yield return Frames(10);state=ScreenState.Menu;yield return Capture(folder,"menu-principal-v4");OpenSelection();yield return Capture(folder,"selecao-v4");MainAction(1);yield return Capture(folder,"power-up-v4");OpenOptions();yield return Capture(folder,"opcoes-v4");bool oldAim=manualAim;manualAim=true;yield return Capture(folder,"opcoes-mira-manual-v8");manualAim=oldAim;OpenDragonDen(ScreenState.Menu);yield return Capture(folder,"dragoes-v5");GoHome();StartRun();time=289;level=8;kills=467;runCoins=170;hp=73;maxHp=100;xp=XpRequired*.64f;for(int i=0;i<6;i++){weapons[i]=i<4?i+2:0;passives[i]=i<3?i+1:0;cooldown[i]=WeaponPeriod(i)*.5f;}for(int i=0;i<16;i++){var e=SpawnEnemy(i%3,false);float a=i*Mathf.PI*2/16;e.p=pos+new Vector2(Mathf.Cos(a),Mathf.Sin(a))*(4+i%3);e.sprite.transform.position=e.p;}dashCooldown=1.5f;yield return Capture(folder,"hud-v2");state=ScreenState.Paused;yield return Capture(folder,"pause-v2");ChooseUpgrades();yield return Capture(folder,"powers-v2");OpenChest();yield return Capture(folder,"chest-v3");var playerSave=save;save=new SaveData();save.curseUnlocks=7;activeCurse=-1;state=ScreenState.CurseChoice;yield return Capture(folder,"maldicoes-v5");save=playerSave;state=ScreenState.Result;chestMessage="A NOITE TE ENCONTROU";hp=0;yield return Capture(folder,"result-v2");ReturnMenu();state=ScreenState.Shop;yield return Capture(folder,"shop-v2");yield return CaptureElements(folder);yield return CaptureGalleryScreens(folder);yield return CaptureManualAim(folder);yield return CaptureDragonMissions(folder);yield return CaptureRelics(folder);yield return CapturePowerPreparation(folder);yield return CaptureIceOwnership(folder);yield return CapturePowerUpHub(folder);yield return CaptureFinal3D(folder);Debug.Log("UI CAPTURE PASS");Application.Quit();}
 IEnumerator CaptureElements(string folder){StartRun();elementPreviewFrozen=true;Array.Clear(weapons,0,weapons.Length);time=35;hp=maxHp=100;for(int i=0;i<4;i++){var e=SpawnEnemy(i==3?5:0,false);e.p=new Vector2(i==0?2:i==1?-2:-4,i==2?-1:1);e.hp=e.maxHp=500;e.sprite.transform.position=e.p;if(i==0)BurnEnemy(e,4,3);if(i==1)e.slow=4;}ReactElement(new Vector2(2,1),.9f,Element.Fire,20);ReactElement(new Vector2(-2,1),1,Element.Ice,10);ReactElement(new Vector2(-4,-1),1,Element.Lightning,20);BurnPlayer(4,3);foreach(var f in fuel)if((f.p-new Vector2(4,-2)).magnitude<.2f)IgniteFuel(f);UpdateElements(.5f);yield return Capture(folder,"combate-elemental-v6");ReactElement(pos,3,Element.Ice,10);UpdateElements(.05f);yield return Capture(folder,"gelo-apaga-fogo-v6");elementPreviewFrozen=false;ReturnMenu();}
 IEnumerator CaptureDragonMissions(string folder){var account=save;int equipped=selectedDragon;save=new SaveData();selectedDragon=-1;OpenDragonDen(ScreenState.Menu);yield return Capture(folder,"missoes-bloqueadas-v9");save.dragonKills=624;save.RefreshDragonMissions();yield return Capture(folder,"missoes-progresso-v9");save.dragonKills=1000;save.bossKills=1;save.wins=1;save.RefreshDragonMissions();SelectDragon(0);yield return Capture(folder,"missoes-concluidas-v9");save=account;selectedDragon=equipped;GoHome();}
 IEnumerator CaptureRelics(string folder){var account=save;int originalHero=heroIndex,originalRelic=inspectedRelic;save=new SaveData();heroIndex=0;OpenRelics(ScreenState.Menu);yield return Capture(folder,"reliquias-bloqueadas-v10");save.relicOwned=255;save.totalKills=250;save.wins=1;TryEquipRelic(0,0);TryEquipRelic(0,1);inspectedRelic=1;yield return Capture(folder,"reliquias-combo-v10");for(int armor=0;armor<4;armor++){inspectedRelic=armor*2;relicAppearancePreview=true;for(int character=0;character<3;character++){armorPreviewHero=character;yield return Capture(folder,"armadura-"+armor+"-heroi-"+character+"-v10");}}relicAppearancePreview=false;heroIndex=1;TryEquipRelic(1,4);TryEquipRelic(1,5);inspectedRelic=4;yield return Capture(folder,"reliquias-cinzas-v10");StartRun();elementPreviewFrozen=true;yield return Capture(folder,"reliquias-hud-v10");save.relicOwned&=~1;DropBossRelic(3,new Vector2(2,0),false);yield return Capture(folder,"reliquias-drop-v10");elementPreviewFrozen=false;ReturnMenu();save=account;heroIndex=originalHero;inspectedRelic=originalRelic;GoHome();}
 IEnumerator CaptureManualAim(string folder){bool mode=manualAim;manualAim=true;StartRun();elementPreviewFrozen=true;Array.Clear(weapons,0,6);weapons[0]=1;weapons[1]=1;pos=Vector2.zero;hero.transform.position=pos;cam.transform.position=new Vector3(0,0,-10);manualAimPoint=new Vector2(4,1);lastAimDirection=manualAimPoint.normalized;aimPointerValid=true;var near=SpawnEnemy(0,false);near.p=new Vector2(-2,0);near.sprite.transform.position=near.p;var picked=SpawnEnemy(2,false);picked.p=manualAimPoint;picked.sprite.transform.position=picked.p;AdvanceWeaponsForCheck(PowerPreparationTime(0)+.02f);UpdateShots(.2f);yield return Capture(folder,"mira-manual-v8");elementPreviewFrozen=false;manualAim=mode;ReturnMenu();}
 IEnumerator CaptureGalleryScreens(string folder){OpenGallery();galleryPaused=true;galleryMode=0;galleryClock=.25f;for(int i=0;i<7;i++){galleryCategory=i;yield return Capture(folder,"galeria-"+i+"-v7");}GoHome();}
 IEnumerator CaptureAnimationMovie(string folder){verifying=true;Application.runInBackground=true;Directory.CreateDirectory(folder);yield return Frames(8);OpenGallery();galleryPaused=true;int shot=0;for(int category=0;category<7;category++){galleryCategory=category;for(int f=0;f<24;f++){galleryMode=f<16?0:2;galleryClock=f/12f;yield return Frames(2);ScreenCapture.CaptureScreenshot(Path.Combine(folder,"animacao-"+(shot++).ToString("0000")+".png"));yield return Frames(2);}}Debug.Log("ANIMATION CAPTURE PASS: "+shot+" frames");Application.Quit();}
 IEnumerator Frames(int count){for(int i=0;i<count;i++)yield return new WaitForEndOfFrame();}
 IEnumerator Capture(string folder,string name){yield return Frames(3);ScreenCapture.CaptureScreenshot(Path.Combine(folder,name+".png"));yield return Frames(8);}
